(()=>{try{var D={gentle:"轻柔",wave:"波浪",pulse:"脉冲",breathe:"呼吸",heartbeat:"心跳",tease:"停顿",gspot:"细波",deep:"深波",devour:"连波",alternate:"交替",climb:"攀升",edge:"渐进",denial:"长停",random:"随机",chaos:"变奏",storm:"快波",tide:"潮涌",punish:"突袭",ruin:"毁断",afterglow:"余韵",stairs:"阶升",countdown:"倒数",knock:"叩击",swing:"摆荡",tremble:"震颤",lock:"锁潮",doubletap:"双叩",mercy:"无赦",stop:"停止"};function N(e){let t=[],s=/[‹<]toy:([a-z]+)(?::\d{1,3})?[›>]/gi,n=String(e).replace(/```[\s\S]*?(?:```|$)/g,r=>" ".repeat(r.length));for(let r of n.matchAll(s)){let c=r[1].toLowerCase();Object.prototype.hasOwnProperty.call(D,c)&&t.push({mode:c,offset:r.index})}return t}var I="<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rifugio · 玩具联动</title><style>/* ============================================================
   AI 玩具（Toy） 全部样式 —— 2026-10-02 由 css-audit 合并
   逐条在 WebKit 里核对过：没生效的删了，不需要的 !important 去了，
   其余按原层叠顺序搬进来。分段标记“原 xx.css”的先后就是层叠顺序，别乱挪。
   以后改这个 App 只改这一个文件。
   ============================================================ */

/*  ── 原 09-standalone-talk-terminal.css ──  */
.toy-hero {
    display: grid;
    gap: 12px;
    padding: 18px;
    border-radius: 30px;
    border: 1px solid rgba(255,255,255,.84);
    box-shadow: 0 22px 44px -32px rgba(104,69,79,.62);
}
.toy-hero-top {
    display: grid;
    grid-template-columns: auto 1fr auto;
    gap: 12px;
    align-items: center;
}
.toy-status-pill {
    min-height: 30px;
    padding: 0 11px;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    background: rgba(143,217,189,.24);
    color: #4b987f;
    font-size: 0.625rem;
    white-space: nowrap;
}
.toy-status-pill.warn {
    background: rgba(244,190,96,.20);
    color: #a36b20;
}
.toy-status-pill.offline {
    background: rgba(177,75,111,.10);
    color: #a95873;
}
.toy-command {
    padding: 10px 12px;
    border-radius: 18px;
    background: #fff8fa;
    border: 1px solid rgba(213,151,167,.12);
}
.toy-command-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}
.toy-command-head b {
    margin: 0;
}
.toy-source-tag {
    flex: 0 0 auto;
    padding: 3px 8px;
    border-radius: 999px;
    background: rgba(229,154,179,.14);
    color: #a95873;
    font-size: 0.5625rem;
    font-weight: 700;
}
.toy-command[data-source="mcp"] {
    border-color: rgba(143,217,189,.28);
}
.toy-command[data-status="error"] {
    border-color: rgba(179,38,63,.25);
}
@media (max-width:420px) {
    .toy-hero-top {
        grid-template-columns: auto 1fr;
    }
    .toy-status-pill {
        grid-column: 1 / -1;
        justify-self: start;
    }
}
.toy-bluefy-page {
    padding-top: 14px;
}
.toy-ble-hero {
    background: radial-gradient(circle at 84% 12%,rgba(181,96,126,.11),transparent 34%),
        radial-gradient(circle at 12% 100%,rgba(237,190,203,.34),transparent 40%),
        linear-gradient(145deg,#fffdfc,#f7e9ed);
}
.toy-ble-hero .toy-heart {
    background: linear-gradient(145deg,#b6677f,#d99aae);
    transition: transform .25s ease,box-shadow .25s ease;
}
.toy-ble-hero .toy-heart.connected {
    transform: scale(1.04);
    box-shadow: 0 0 0 7px rgba(163,92,115,.10),0 16px 30px -18px rgba(104,42,61,.74);
}
.toy-hero-copy {
    min-width: 0;
}
.toy-hero-copy>small {
    color: rgba(104,69,79,.38);
    font-size: .5rem;
    letter-spacing: .18em;
}
.toy-hero-copy h3 {
    margin: 2px 0 0;
    color: #68454f;
    font-size: 1.375rem;
    font-weight: 780;
    line-height: 1.1;
}
.toy-hero-copy p {
    margin-top: 4px;
    color: rgba(104,69,79,.50);
    font-size: .625rem;
}
.toy-bluefy-note {
    padding-top: 2px;
}
.toy-transport-strip {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    margin-top: 2px;
}
.toy-transport-strip span {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 10px;
    border-radius: 999px;
    background: rgba(122,105,115,.08);
    color: rgba(83,61,73,.56);
    font-size: 11px;
    font-weight: 700;
    border: 1px solid transparent;
}
.toy-transport-strip span i {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: #b9adb2;
    box-shadow: 0 0 0 3px rgba(185,173,178,.12);
}
.toy-transport-strip span.online {
    color: #8b6740;
    background: rgba(244,190,96,.11);
}
.toy-transport-strip span.online i {
    background: #e2aa52;
}
.toy-transport-strip span.connected {
    color: #8d355a;
    background: rgba(177,75,111,.10);
}
.toy-transport-strip span.connected i {
    background: #b14b6f;
    box-shadow: 0 0 0 3px rgba(177,75,111,.13);
}
.toy-transport-strip span.active {
    border-color: rgba(177,75,111,.30);
    box-shadow: 0 5px 16px rgba(142,67,92,.10);
}
.toy-transport-strip span.active::after {
    content: 'ACTIVE';
    font-size: 8px;
    letter-spacing: .08em;
    opacity: .72;
}
.toy-live-controls,
.toy-pattern-card {
    margin-top: 12px;
}
.toy-section-title {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
}
.toy-section-title>div {
    min-width: 0;
}
.toy-section-title>span {
    flex: 0 0 auto;
    padding: 4px 8px;
    border-radius: 999px;
    background: rgba(170,101,124,.09);
    color: rgba(123,66,86,.52);
    font-size: .5rem;
    font-weight: 750;
    letter-spacing: .08em;
}
.toy-quiet-action {
    flex: 0 0 auto;
    padding: 6px 10px;
    color: #9b5970;
    background: rgba(176,101,127,.08);
    font-size: .5625rem;
}
.toy-command[data-status="cancelled"] {
    opacity: .62;
}
.toy-attribution {
    padding: 2px 8px 8px;
    color: rgba(104,69,79,.30);
    font-size: .5rem;
    text-align: center;
}
.toy-attribution a {
    color: rgba(151,80,105,.56);
    text-decoration: underline;
    text-underline-offset: 2px;
}
@media (max-width:390px) {
    .toy-bluefy-page {
        padding-left: 11px;
        padding-right: 11px;
    }
    .toy-live-controls,
    .toy-pattern-card,
    .toy-ble-hero {
        padding: 14px;
        border-radius: 24px;
    }
}


/* ============================================================
   玩具页三套皮肤（2026-10-04）：果冻 / 糖果 / 棉花糖，+ 随机（每次打开随机一套）。
   只换样式不碰逻辑：皮肤挂在 .toy-app-shell[data-skin]，页面右上“美化”下拉切换，
   选择存 localStorage（rifugio-toy-skin-v1），棉花糖口味存 rifugio-toy-cotton-flavor-v1。
   悬浮窗（.toy-ble-sheet / .toy-float-orb）在 shell 外面，不受影响。
   ① 通用布局  ② 果冻（B3 小样原样）  ③ 糖果（ibaotu 糖果按钮参考）  ④ 棉花糖（Cotton Candy UI kit 参考）
   ============================================================ */

/* ① 通用布局 —— 三套共用 */
#app .toy-app-shell[data-skin] { --spring: cubic-bezier(.3,2.1,.45,.9); position: relative; }
#app .toy-app-shell[data-skin] .toy-scroll { padding: 14px 16px calc(env(safe-area-inset-bottom) + 30px); }
#app .toy-app-shell[data-skin] .toy-card { margin-bottom: 16px; padding: 18px 16px 16px; position: relative; max-width: 100%; }
#app .toy-app-shell[data-skin] .toy-hero { position: relative; padding: 18px 16px 16px; margin-bottom: 16px; gap: 0; }
#app .toy-app-shell[data-skin] .toy-hero > * + * { margin-top: 10px; }
#app .toy-app-shell[data-skin] .toy-hero-top { grid-template-columns: auto 1fr; align-items: center; }
#app .toy-app-shell[data-skin] .toy-hero-tools { grid-column: 1 / -1; display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; }
#app .toy-app-shell[data-skin] .toy-status-pill { grid-column: auto; min-height: 30px; padding: 0 12px; font-size: 12px; font-weight: 700; }
#app .toy-app-shell[data-skin] .toy-skin-pick { position: relative; display: inline-flex; align-items: center; gap: 4px; height: 30px; padding: 0 24px 0 12px; margin: 0 0 0 auto; border-radius: 999px; font-size: 12px; font-weight: 700; }
#app .toy-app-shell[data-skin] .toy-skin-pick small { display: inline; margin: 0; font-size: 12px; line-height: 1; color: inherit; opacity: .7; }
#app .toy-app-shell[data-skin] .toy-skin-pick select { -webkit-appearance: none; appearance: none; border: 0; background: transparent; padding: 0; margin: 0; color: inherit; font: inherit; font-weight: 700; outline: 0; min-width: 0; }
#app .toy-app-shell[data-skin] .toy-skin-pick::after { content: ""; position: absolute; right: 10px; top: 50%; width: 5px; height: 5px; border-right: 1.6px solid currentColor; border-bottom: 1.6px solid currentColor; transform: translateY(-70%) rotate(45deg); pointer-events: none; }
#app .toy-app-shell[data-skin] .toy-heart { width: 52px; height: 52px; border-radius: 50%; font-size: 23px; position: relative; }
#app .toy-app-shell[data-skin] .toy-hero-copy > small { display: block; font-size: 9px; letter-spacing: 1px; white-space: nowrap; }
#app .toy-app-shell[data-skin] .toy-hero-copy h3 { font-size: 26px; font-weight: 700; line-height: 1.15; }
#app .toy-app-shell[data-skin] .toy-hero-copy p { font-size: 13px; margin-top: 2px; }
#app .toy-app-shell[data-skin] .toy-connect-wide { width: 100%; min-height: 48px; font-size: 16px; font-weight: 700; letter-spacing: 0; position: relative; }
#app .toy-app-shell[data-skin] .toy-status { font-size: 13px; }
#app .toy-app-shell[data-skin] .toy-transport-strip { display: flex; gap: 8px; flex-wrap: nowrap; }
#app .toy-app-shell[data-skin] .toy-transport-strip span { flex: 1; min-width: 0; padding: 8px 12px; font-size: 13px; font-weight: 600; }
#app .toy-app-shell[data-skin] .toy-transport-strip span.active::after { content: none; }
#app .toy-app-shell[data-skin] .toy-bluefy-note { font-size: 11px; line-height: 1.6; padding-top: 0; }
#app .toy-app-shell[data-skin] .toy-section-title { gap: 10px; }
#app .toy-app-shell[data-skin] .toy-section-title b { font-size: 17px; }
#app .toy-app-shell[data-skin] .toy-section-title small { font-size: 12px; line-height: 1.5; margin-top: 3px; }
#app .toy-app-shell[data-skin] .toy-section-title > span { height: fit-content; padding: 3px 10px; font-size: 11px; letter-spacing: 0; white-space: nowrap; }
#app .toy-app-shell[data-skin] .toy-channel-block { padding: 18px 0 0; border-bottom: 0; }
#app .toy-app-shell[data-skin] .toy-channel-block:first-of-type { padding-top: 14px; }
#app .toy-app-shell[data-skin] .toy-channel-head { grid-template-columns: 32px minmax(0,1fr) auto; gap: 10px; margin-bottom: 4px; }
#app .toy-app-shell[data-skin] .toy-channel-head b { font-size: 15px; }
#app .toy-app-shell[data-skin] .toy-channel-head strong { font-size: 13px; font-weight: 700; }
#app .toy-app-shell[data-skin] .toy-channel-icon { width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; font-size: 0; }
#app .toy-app-shell[data-skin] .toy-channel-icon svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
#app .toy-app-shell[data-skin] .toy-channel-block > input[type="range"] { -webkit-appearance: none; appearance: none; width: 100%; height: 32px; margin: 6px 0 0; background: transparent; outline: 0; --sx: 1; --sy: 1; --p: 0%; }
#app .toy-app-shell[data-skin] .toy-mode-row { gap: 8px; margin-top: 12px; }
#app .toy-app-shell[data-skin] .toy-mode-row button,
#app .toy-app-shell[data-skin] .toy-pattern-channel-tabs button,
#app .toy-app-shell[data-skin] .toy-pattern-options button { min-height: 38px; height: 38px; font-size: 15px; font-weight: 700; position: relative; }
#app .toy-app-shell[data-skin] .toy-pattern-channel-tabs { gap: 8px; margin-top: 12px; }
#app .toy-app-shell[data-skin] .toy-pattern-options { gap: 8px; margin-top: 12px; }
#app .toy-app-shell[data-skin] .toy-emergency-stop { display: flex; align-items: center; justify-content: center; gap: 10px; width: 100%; min-height: 54px; margin: 0 0 16px; font-size: 19px; font-weight: 700; letter-spacing: 0; position: relative; }
#app .toy-app-shell[data-skin] .toy-emergency-stop svg { width: 20px; height: 20px; fill: currentColor; stroke: currentColor; stroke-width: 1; }
#app .toy-app-shell[data-skin] .toy-emergency-stop em { font-style: normal; }
#app .toy-app-shell[data-skin] .talk-switch { display: flex; align-items: center; gap: 12px; min-height: 0; padding: 0; margin: 14px 0 0; background: transparent; font-size: 15px; color: inherit; cursor: pointer; }
#app .toy-app-shell[data-skin] .talk-switch input[type="checkbox"] { -webkit-appearance: none; appearance: none; flex: 0 0 52px; width: 52px; height: 32px; min-width: 52px; margin: 0; padding: 0; border-radius: 16px; position: relative; outline: 0; cursor: pointer; }
#app .toy-app-shell[data-skin] .talk-switch input[type="checkbox"]::after { content: ""; position: absolute; top: 2px; left: 2px; width: 26px; height: 26px; border-radius: 50%; transition: transform .55s var(--spring), width .3s var(--spring); }
#app .toy-app-shell[data-skin] .talk-switch input[type="checkbox"]:checked::after { transform: translateX(20px); }
#app .toy-app-shell[data-skin] .talk-switch:active input[type="checkbox"]::after { width: 36px; }
#app .toy-app-shell[data-skin] .talk-switch:active input[type="checkbox"]:checked::after { transform: translateX(10px); }
#app .toy-app-shell[data-skin] .talk-switch span { font-size: 15px; color: inherit; }
#app .toy-app-shell[data-skin] .toy-command { margin: 0; padding: 10px 14px; }
#app .toy-app-shell[data-skin] .toy-command-head b { font-size: 14px; }
#app .toy-app-shell[data-skin] .toy-command small { font-size: 12px; }
#app .toy-app-shell[data-skin] .toy-source-tag { padding: 2px 8px; font-size: 10px; }
#app .toy-app-shell[data-skin] .toy-quiet-action { padding: 5px 14px; font-size: 13px; height: fit-content; }
#app .toy-app-shell[data-skin] .toy-attribution { font-size: 11px; }
#app .toy-app-shell[data-skin] button { transition: transform .55s var(--spring), box-shadow .2s; -webkit-tap-highlight-color: transparent; }
#app .toy-app-shell[data-skin] button:active { transform: scale(1.07,.88); transition-duration: .1s; }
@media (max-width:390px) { #app .toy-app-shell[data-skin] .toy-scroll { padding-left: 12px; padding-right: 12px; } }

/* ② 果冻（B3 小样原样） */
#app .toy-app-shell[data-skin="jelly"] {
    color: #5a1f3d;
    background:
        radial-gradient(circle 170px at -2% 10%, rgba(255,111,168,.78), transparent 72%),
        radial-gradient(circle 150px at 104% 2%, rgba(127,216,255,.75), transparent 72%),
        radial-gradient(circle 160px at 106% 42%, rgba(181,139,255,.78), transparent 72%),
        radial-gradient(circle 170px at -4% 74%, rgba(255,179,107,.72), transparent 72%),
        linear-gradient(165deg,#ffeaf2,#ffd3e4 50%,#ecd2ff) !important;
}
#app .toy-app-shell[data-skin="jelly"] :is(.toy-card, .toy-hero, .toy-status-pill, .toy-skin-pick, .toy-connect-wide, .toy-transport-strip span, .toy-section-title > span, .toy-channel-icon, .toy-quiet-action, .toy-source-tag) {
    background: linear-gradient(145deg,rgba(255,170,205,.2),rgba(255,255,255,.07) 55%,rgba(255,170,205,.14)) !important;
    -webkit-backdrop-filter: blur(18px) saturate(170%); backdrop-filter: blur(18px) saturate(170%);
    border: 1px solid rgba(255,255,255,.4) !important;
    box-shadow: inset 0 0 0 1px rgba(255,255,255,.55), inset 2px 3px 5px rgba(255,255,255,.65), inset -2px -4px 7px rgba(255,105,165,.28), inset 0 0 12px 3px rgba(255,255,255,.28), 0 10px 22px -10px rgba(200,40,110,.4) !important;
}
#app .toy-app-shell[data-skin="jelly"] :is(.toy-card, .toy-hero) {
    border-radius: 30px !important; color: #5a1f3d !important;
    box-shadow: inset 0 0 0 1px rgba(255,255,255,.55), inset 3px 4px 8px rgba(255,255,255,.55), inset -3px -6px 12px rgba(255,105,165,.22), inset 0 0 22px 4px rgba(255,255,255,.25), 0 14px 30px -12px rgba(200,40,110,.4) !important;
}
#app .toy-app-shell[data-skin="jelly"] :is(.toy-card, .toy-hero)::after { content: ""; position: absolute; left: 7%; top: 9px; width: 34%; height: 12px; border-radius: 50%; background: rgba(255,255,255,.55); filter: blur(4px); opacity: .7; transform: rotate(-8deg); pointer-events: none; }
#app .toy-app-shell[data-skin="jelly"] .toy-card b, #app .toy-app-shell[data-skin="jelly"] .toy-section-title b { color: #8e1d50; }
#app .toy-app-shell[data-skin="jelly"] .toy-card small, #app .toy-app-shell[data-skin="jelly"] small, #app .toy-app-shell[data-skin="jelly"] .toy-status, #app .toy-app-shell[data-skin="jelly"] .toy-hero-copy p { color: #9b4c72; }
#app .toy-app-shell[data-skin="jelly"] .toy-hero-copy h3 { color: #b02461; }
#app .toy-app-shell[data-skin="jelly"] .toy-hero-copy > small { color: #9b4c72; }
#app .toy-app-shell[data-skin="jelly"] .toy-status.error { color: #c4112f; }
#app .toy-app-shell[data-skin="jelly"] :is(.toy-status-pill, .toy-skin-pick, .toy-section-title > span, .toy-source-tag, .toy-quiet-action) { color: #b02461; border-radius: 999px; }
#app .toy-app-shell[data-skin="jelly"] .toy-status-pill.warn { color: #a36b20; }
#app .toy-app-shell[data-skin="jelly"] .toy-status-pill.offline { color: #a95873; }
#app .toy-app-shell[data-skin="jelly"] .toy-heart {
    color: #fff; border: 1px solid rgba(255,255,255,.55);
    background: radial-gradient(circle at 32% 26%, rgba(255,255,255,.7) 0 8%, transparent 22%), rgba(255,80,150,.4) !important;
    -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
    box-shadow: inset 0 0 0 1px rgba(255,255,255,.6), inset 2px 3px 5px rgba(255,255,255,.7), inset -2px -4px 7px rgba(220,30,100,.3), 0 6px 14px -6px rgba(255,60,130,.5) !important;
}
